const resolveBlock = `-- name: ResolveBlock :one
SELECT block_id, rel_path, body, line, byte_start, byte_end
FROM pkm_blocks
WHERE block_id = ?
`

type ResolveBlockRow struct {
	BlockID   string
	RelPath   string
	Body      string
	Line      int64
	ByteStart int64
	ByteEnd   int64
}

func (q *Queries) ResolveBlock(ctx context.Context, blockID string) (ResolveBlockRow, error) {
	row := q.queryRow(ctx, q.resolveBlockStmt, resolveBlock, blockID)
	var i ResolveBlockRow
	err := row.Scan(
		&i.BlockID,
		&i.RelPath,
		&i.Body,
		&i.Line,
		&i.ByteStart,
		&i.ByteEnd,
	)
	return i, err
}

const searchShortTerms = `-- name: SearchShortTerms :many
SELECT rel_path,
       CAST((CASE WHEN INSTR(lower(title), ?1) > 0 THEN 4.0 ELSE 0.0 END) +
       (CASE WHEN INSTR(lower(tags_json), ?1) > 0 THEN 2.0 ELSE 0.0 END) +
       (CASE WHEN INSTR(lower(body), ?1) > 0 THEN 1.0 ELSE 0.0 END) AS REAL) AS s
FROM pkm_notes
WHERE INSTR(lower(title), ?1) > 0 OR INSTR(lower(tags_json), ?1) > 0 OR INSTR(lower(body), ?1) > 0
ORDER BY s DESC
LIMIT ?2
`

type SearchShortTermsParams struct {
	Term       string
	LimitCount int64
}

type SearchShortTermsRow struct {
	RelPath string
	S       float64
}

func (q *Queries) SearchShortTerms(ctx context.Context, arg SearchShortTermsParams) ([]SearchShortTermsRow, error) {
	rows, err := q.query(ctx, q.searchShortTermsStmt, searchShortTerms, arg.Term, arg.LimitCount)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchShortTermsRow{}
	for rows.Next() {
		var i SearchShortTermsRow
		if err := rows.Scan(&i.RelPath, &i.S); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateNote = `-- name: UpdateNote :exec
UPDATE pkm_notes
SET slug = ?, title = ?, tier = ?, sha256 = ?, frontmatter_json = ?, tags_json = ?, body = ?, updated_at_ms = ?
WHERE id = ?
`

type UpdateNoteParams struct {
	Slug            string
	Title           string
	Tier            string
	Sha256          string
	FrontmatterJson string
	TagsJson        string
	Body            string
	UpdatedAtMs     int64
	ID              int64
}

func (q *Queries) UpdateNote(ctx context.Context, arg UpdateNoteParams) error {
	_, err := q.exec(ctx, q.updateNoteStmt, updateNote,
		arg.Slug,
		arg.Title,
		arg.Tier,
		arg.Sha256,
		arg.FrontmatterJson,
		arg.TagsJson,
		arg.Body,
		arg.UpdatedAtMs,
		arg.ID,
	)
	return err
}

const upsertVector = `-- name: UpsertVector :exec
INSERT INTO _vec_pkm_vectors (dataset_id, id, content, meta, embedding)
VALUES (?, ?, ?, ?, ?)
ON CONFLICT(dataset_id, id) DO UPDATE SET
    content = excluded.content,
    meta = excluded.meta,
    embedding = excluded.embedding
`

type UpsertVectorParams struct {
	DatasetID string
	ID        string
	Content   sql.NullString
	Meta      sql.NullString
	Embedding []byte
}

func (q *Queries) UpsertVector(ctx context.Context, arg UpsertVectorParams) error {
	_, err := q.exec(ctx, q.upsertVectorStmt, upsertVector,
		arg.DatasetID,
		arg.ID,
		arg.Content,
		arg.Meta,
		arg.Embedding,
	)
	return err
}
